// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(
        string calldata name,
        string calldata symbol,
        address oracle,
        uint8 payoffTypeRaw,
        uint8 payoffDirectionRaw,
        bytes30 data,
        uint64 maintenanceRaw,
        uint64 fundingFeeRaw,
        uint64 makerFeeRaw,
        uint64 takerFeeRaw,
        uint64 positionFeeRaw,
        uint64 makerLimitRaw,
        int128 minRateRaw,
        int128 maxRateRaw,
        int128 targetRateRaw,
        uint128 targetUtilizationRaw
    ) public {
        vm.assume(oracle != address(0));
        vm.assume(oracle.code.length > 0);
        vm.assume(payoffTypeRaw <= 1);
        vm.assume(payoffDirectionRaw <= 1);

        C.ProductInfo memory info;
        info.name = name;
        info.symbol = symbol;
        info.oracle = IOracleProvider(oracle);
        info.payoffDefinition.payoffType = PayoffDefinitionLib.PayoffType(payoffTypeRaw);
        info.payoffDefinition.payoffDirection = PayoffDefinitionLib.PayoffDirection(payoffDirectionRaw);
        info.payoffDefinition.data = data;
        info.maintenance = UFixed18.wrap(maintenanceRaw);
        info.fundingFee = UFixed18.wrap(fundingFeeRaw);
        info.makerFee = UFixed18.wrap(makerFeeRaw);
        info.takerFee = UFixed18.wrap(takerFeeRaw);
        info.positionFee = UFixed18.wrap(positionFeeRaw);
        info.makerLimit = UFixed18.wrap(makerLimitRaw);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(minRateRaw),
            maxRate: PackedFixed18.wrap(maxRateRaw),
            targetRate: PackedFixed18.wrap(targetRateRaw),
            targetUtilization: PackedUFixed18.wrap(targetUtilizationRaw)
        });

        vm.prank(address(c.controller()));
        c.initialize(info);

        PayoffDefinition memory storedDef = c.payoffDefinition();
        PayoffDefinition memory expectedDef = info.payoffDefinition;
        assertTrue(
            storedDef.payoffType == expectedDef.payoffType &&
            storedDef.payoffDirection == expectedDef.payoffDirection &&
            storedDef.data == expectedDef.data
        );
    }
}

