pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 payoffTypeRaw, uint8 payoffDirectionRaw, bytes30 dataRaw) public {
        // Bound to valid PayoffType and PayoffDirection enum values (0-2 for type, 0-1 for direction)
        vm.assume(payoffTypeRaw <= 2);
        vm.assume(payoffDirectionRaw <= 1);

        // Deploy a mock oracle and controller
        MockOracle oracle = new MockOracle();
        MockController controller = new MockController(address(oracle));

        // Build the ProductInfo
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(address(oracle));
        info.payoffDefinition.payoffType = PayoffDefinitionLib.PayoffType(payoffTypeRaw);
        info.payoffDefinition.payoffDirection = PayoffDefinitionLib.PayoffDirection(payoffDirectionRaw);
        info.payoffDefinition.data = dataRaw;
        info.maintenance = UFixed18.wrap(0.1e18);
        info.fundingFee = UFixed18.wrap(0.01e18);
        info.makerFee = UFixed18.wrap(0.001e18);
        info.takerFee = UFixed18.wrap(0.002e18);
        info.positionFee = UFixed18.wrap(0.0005e18);
        info.makerLimit = UFixed18.wrap(1000e18);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(int128(0.01e18)),
            maxRate: PackedFixed18.wrap(int128(1.0e18)),
            targetRate: PackedFixed18.wrap(int128(0.1e18)),
            targetUtilization: PackedUFixed18.wrap(uint128(0.8e18))
        });

        // Initialize through the controller
        vm.prank(address(controller));
        c.initialize(info);

        // Read back the payoff definition
        PayoffDefinition memory returned = c.payoffDefinition();

        // The returned definition must exactly match what was passed
        assertTrue(
            returned.payoffType == info.payoffDefinition.payoffType &&
            returned.payoffDirection == info.payoffDefinition.payoffDirection &&
            returned.data == info.payoffDefinition.data
        );
    }
}

contract MockOracle is IOracleProvider {
