contract MockController is IController {
    address private _oracle;
    ICollateral private _collateral;
    IIncentivizer private _incentivizer;
    IBeacon private _productBeacon;
    IMultiInvoker private _multiInvoker;
    UFixed18 private _protocolFee;
    UFixed18 private _minFundingFee;
    UFixed18 private _liquidationFee;
    UFixed18 private _incentivizationFee;
    UFixed18 private _minCollateral;
    uint256 private _programsPerProduct;
    address private _pauser;
    bool private _paused;
    mapping(uint256 => Coordinator) private _coordinators;
    mapping(IProduct => uint256) private _productCoordinator;
    uint256 private _nextCoordinatorId = 1;

    constructor(address oracle) {
        _oracle = oracle;
        _collateral = ICollateral(address(0));
        _incentivizer = IIncentivizer(address(0));
        _productBeacon = IBeacon(address(0));
        _multiInvoker = IMultiInvoker(address(0));
        _minFundingFee = UFixed18.wrap(0);
    }

    function isProduct(IProduct product) external view returns (bool) {
        return _productCoordinator[product] != 0 || _nextCoordinatorId == 1;
    }

    function owner(uint256 coordinatorId) external view returns (address) {
        return _coordinators[coordinatorId].owner;
    }
    function coordinatorFor(IProduct product) external view returns (uint256) {
        uint256 id = _productCoordinator[product];
        if (id == 0 && _nextCoordinatorId == 1) {
            return 1;
        }
        return id;
    }
    function incentivizer() external view returns (IIncentivizer) {
        return _incentivizer;
    }
    function collateral() external view returns (ICollateral) {
        return _collateral;
    }
    function productBeacon() external view returns (IBeacon) {
        return _productBeacon;
    }
    function multiInvoker() external view returns (IMultiInvoker) {
        return _multiInvoker;
    }
    function coordinators(uint256) external view returns (Coordinator memory) {
        return _coordinators[1];
    }
    function protocolFee() external view returns (UFixed18) { return _protocolFee; }
    function minFundingFee() external view returns (UFixed18) { return _minFundingFee; }
    function liquidationFee() external view returns (UFixed18) { return _liquidationFee; }
    function incentivizationFee() external view returns (UFixed18) { return _incentivizationFee; }
    function minCollateral() external view returns (UFixed18) { return _minCollateral; }
    function programsPerProduct() external view returns (uint256) { return _programsPerProduct; }
    function pauser() external view returns (address) { return _pauser; }
    function paused() external view returns (bool) { return _paused; }
    function initialize(ICollateral, IIncentivizer, IBeacon) external {}
    function createCoordinator() external returns (uint256) { return 0; }
    function updateCoordinatorPendingOwner(uint256, address) external {}
    function acceptCoordinatorOwner(uint256) external {}
    function updateCoordinatorTreasury(uint256, address) external {}
    function createProduct(uint256, IProduct.ProductInfo calldata) external returns (IProduct) { return IProduct(address(0)); }
    function updateCollateral(ICollateral) external {}
    function updateIncentivizer(IIncentivizer) external {}
    function updateProductBeacon(IBeacon) external {}
    function updateMultiInvoker(IMultiInvoker) external {}
    function updateProtocolFee(UFixed18) external {}
    function updateMinFundingFee(UFixed18) external {}
    function updateLiquidationFee(UFixed18) external {}
    function updateIncentivizationFee(UFixed18) external {}
    function updateMinCollateral(UFixed18) external {}
    function updateProgramsPerProduct(uint256) external {}
    function updatePauser(address) external {}
    function updatePaused(bool) external {}
    function owner() external view returns (address) { return address(0); }
    function owner(IProduct) external view returns (address) { return address(0); }
    function treasury() external view returns (address) { return address(0); }
    function treasury(uint256) external view returns (address) { return address(0); }
    function treasury(IProduct) external view returns (address) { return address(0); }
}

