pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(
        address oracle,
        uint8 payoffTypeRaw,
        uint8 payoffDirectionRaw,
        bytes30 data
    ) public {
        // 1. Restrict payoffType / payoffDirection to admissible small values
        vm.assume(payoffTypeRaw <= 5);
        vm.assume(payoffDirectionRaw <= 3);

        // 2. Assemble a valid ProductInfo; MUST embed the fuzzed payoff definition
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.payoffDefinition = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(payoffTypeRaw),
            PayoffDefinitionLib.PayoffDirection(payoffDirectionRaw),
            data
        );
        info.oracle = IOracleProvider(oracle);
        info.maintenance = UFixed18.wrap(0.1e18);
        info.fundingFee = UFixed18.wrap(0.01e18);
        info.makerFee = UFixed18.wrap(0.005e18);
        info.takerFee = UFixed18.wrap(0.005e18);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(1_000_000e18);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0.1e18),
            PackedFixed18.wrap(0.5e18),
            PackedFixed18.wrap(0.2e18),
            PackedUFixed18.wrap(0.8e18)
        );

        // 3. Initialize the contract (if it reverts the fuzz seed is just skipped)
        try c.initialize(info) {} catch {
            return;
        }

        // 4. Read back the stored definition
        PayoffDefinition memory stored = c.payoffDefinition();

        // 5. GENERAL RULE: stored definition MUST equal the fuzzed input definition
        assertTrue(
            stored.payoffType == info.payoffDefinition.payoffType &&
            stored.payoffDirection == info.payoffDefinition.payoffDirection &&
            stored.data == info.payoffDefinition.data
        );
    }
}

