pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, bytes30 data) public {
        // Bound to valid enum values (0=PASSTHROUGH, 1=...)
        payoffType = uint8(bound(payoffType, 0, 255));
        payoffDirection = uint8(bound(payoffDirection, 0, 255));

        // Build ProductInfo with fuzzed payoffDefinition
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.payoffDefinition = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(payoffType),
            PayoffDefinitionLib.PayoffDirection(payoffDirection),
            data
        );
        // Use a dummy oracle address (must be a contract to pass isContract check)
        info.oracle = IOracleProvider(address(new OracleMock()));
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedUFixed18.wrap(0)
        );

        // Only test valid payoff definitions to avoid reverts in both versions
        vm.assume(info.payoffDefinition.valid());

        // Initialize as the controller (C expects msg.sender to be the controller)
        vm.mockCall(
            address(this),
            abi.encodeWithSelector(IController.isProduct.selector, address(c)),
            abi.encode(true)
        );
        vm.prank(address(this));
        c.initialize(info);

        // Read the actual stored payoffDefinition
        PayoffDefinition memory stored = c.payoffDefinition();

        // Assert: the returned definition must match the initial one
        assertTrue(
            stored.payoffType == info.payoffDefinition.payoffType &&
            stored.payoffDirection == info.payoffDefinition.payoffDirection &&
            stored.data == info.payoffDefinition.data
        );
    }
}

