// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 rawPayoffType, uint8 rawPayoffDirection, bytes30 data) public {
        // Bound to valid enum values: PayoffType has 3 values (0,1,2), PayoffDirection has 2 (0,1)
        uint8 payoffTypeVal = rawPayoffType % 3;
        uint8 payoffDirectionVal = rawPayoffDirection % 2;
        // Ensure not all zero to test non-trivial definition
        vm.assume(payoffTypeVal != 0 || payoffDirectionVal != 0 || data != bytes30(0));

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType(payoffTypeVal),
                payoffDirection: PayoffDefinitionLib.PayoffDirection(payoffDirectionVal),
                data: data
            }),
            oracle: IOracleProvider(address(0x0000000000000000000000000000000000000001)),
            maintenance: UFixed18.wrap(0.1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(1e18),
                targetRate: PackedFixed18.wrap(0.1e18),
                targetUtilization: PackedUFixed18.wrap(0.8e18)
            })
        });

        // Deploy a minimal oracle contract to satisfy isContract check
        MockOracle oracle = new MockOracle();
        info.oracle = oracle;

        vm.prank(address(0x123)); // Initializer must be controller; we mock the controller check? Actually initialize reads msg.sender as controller.
        // To properly initialize, we need the contract to accept msg.sender as controller, but controller() returns address from __UControllerProvider__initialize.
        // We'll deploy a mock controller that allows the product initialization.
        MockController controller = new MockController();
        // Set productBeacon to self? Actually product creation flow is complex. We'll just set storage directly using vm.store, but that is forbidden.
        // Alternative: we can call initialize directly with a mock controller address that delegates to the product? No, UInitializable only checks version.
        // We'll use vm.prank with a contract address that is the controller, but controller.isProduct check is called for some modifiers.
        // Since we only call payoffDefinition(), we don't need controller to work; we just need initialize to succeed.
        // initialize() calls __UControllerProvider__initialize(msg.sender) which stores msg.sender as controller.
        // We'll prank as a contract address that has code (to pass isContract check).
        vm.prank(address(controller));
        c.initialize(info);

        PayoffDefinition memory returned = c.payoffDefinition();
        assertTrue(
            returned.payoffType == info.payoffDefinition.payoffType &&
            returned.payoffDirection == info.payoffDefinition.payoffDirection &&
            returned.data == info.payoffDefinition.data
        );
    }
}

