contract MockController {
    ICollateral public collateral;
    IIncentivizer public incentivizer;
    IBeacon public productBeacon;
    IMultiInvoker public multiInvoker;
    function isProduct(IProduct) external pure returns (bool) { return true; }
    function coordinatorFor(IProduct) external pure returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return address(this); }
    function minFundingFee() external pure returns (UFixed18) { return UFixed18.wrap(0); }
    function paused() external pure returns (bool) { return false; }
}

interface IController {
    function isProduct(IProduct) external pure returns (bool);
    function coordinatorFor(IProduct) external pure returns (uint256);
    function owner(uint256) external view returns (address);
    function minFundingFee() external pure returns (UFixed18);
    function paused() external pure returns (bool);
    function collateral() external view returns (ICollateral);
    function incentivizer() external view returns (IIncentivizer);
}

interface IProduct {
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        IOracleProvider oracle;
        UFixed18 maintenance;
        UFixed18 fundingFee;
        UFixed18 makerFee;
        UFixed18 takerFee;
        UFixed18 positionFee;
        UFixed18 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }
}

interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
}

interface ICollateral {}
interface IIncentivizer {}
interface IBeacon {}
interface IMultiInvoker {}

// The following types and libraries are required by the test; minimal stubs.
type Fixed18 is int256;
type UFixed18 is uint256;
type PackedFixed18 is int128;
type PackedUFixed18 is uint128;

struct PayoffDefinition {
    PayoffDefinitionLib.PayoffType payoffType;
    PayoffDefinitionLib.PayoffDirection payoffDirection;
    bytes30 data;
}

library PayoffDefinitionLib {
    enum PayoffType { PASS, CALL, PUT }
    enum PayoffDirection { LONG, SHORT }
}

struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

// Minimal C import assumes C_under_test.sol contains the corrected or original code.
// The test compiles against the original C under test.

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract MockOracleProvider {
    IOracleProvider.OracleVersion public current;

    function setCurrent(IOracleProvider.OracleVersion memory version) external {
        current = version;
    }

    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return current;
    }

    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return current;
    }

    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return current;
    }

    function isContract(address) external pure returns (bool) {
        return true;
    }
}

contract InvMutTest is Test {
    C c;
    MockOracleProvider oracle;

    function setUp() public {
        oracle = new MockOracleProvider();
        c = new C();
    }

    function testFuzz_property(int256 price, bytes30 data) public {
        // Bound to avoid overflow in Fixed18 math; price is int256, Fixed18 uses int256 range.
        price = int256(bound(uint256(int256(price >= 0 ? price : -price)), 0, type(int128).max));

        // Setup oracle version
        IOracleProvider.OracleVersion memory version = IOracleProvider.OracleVersion({
            version: 1,
            timestamp: uint64(block.timestamp),
            price: Fixed18.wrap(price)
        });
        oracle.setCurrent(version);

        // Define a payoff definition that does a non-identity transform (e.g., passthrough with no change is NOT enough; use a non-zero constant shift)
        // PayoffType = 0 (PASSTHROUGH) is the only valid one for simple transform? Actually PayoffDefinitionLib has several types.
        // We use PASSTHROUGH with data = 0 -> identity, so bug won't trigger. Instead use a CALL payoff type that applies a multiplier?
        // The PayoffDefinition transform logic: for type CALL, it may use data as a leverage, but simplest is to use a CONSTANT type which adds a constant.
        // Since we cannot import PayoffDefinitionLib, we encode manually: payoffType=2 (CONSTANT), payoffDirection=0 (LONG), data = bytes30(uint240(someConstant)).
        // The constant is added to price. Let's use a constant shift of 1e18 (ONE).
        bytes30 shift = bytes30(uint240(1e18));
        PayoffDefinition memory payoff = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.wrap(2),
            payoffDirection: PayoffDefinitionLib.PayoffDirection.wrap(0),
            data: shift
        });

        // Initialize C with the oracle and payoff definition
        // We need to bypass the modifier onlyInitializer: use a helper or deploy a new C that can be initialized? C's initialize is external initializer(1).
        // Since setUp() deploys C but does not initialize, we cannot call initialize directly because initializer requires _version < 1.
        // We need to deploy a fresh C and initialize it within the test.
        C newC = new C();
        vm.prank(address(this)); // msg.sender used as controller
        // But initialize checks that msg.sender is a contract (isContract), and then stores it as controller.
        // Since this test contract is a contract, it will pass isContract check.
        newC.initialize(IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: payoff,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(0.1e18),
            fundingFee: UFixed18.wrap(0.01e18),
            makerFee: UFixed18.wrap(0.01e18),
            takerFee: UFixed18.wrap(0.01e18),
            positionFee: UFixed18.wrap(0.01e18),
            makerLimit: UFixed18.wrap(10000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(1e18),
                targetRate: PackedFixed18.wrap(0.8e18),
                targetUtilization: PackedUFixed18.wrap(0.8e18)
            })
        }));

        // Now call currentVersion on the initialized contract
        IOracleProvider.OracleVersion memory result = newC.currentVersion();

        // Reference contract should return transformed price: original price + shift (1e18) because CONSTANT type adds the constant.
        Fixed18 expectedPrice = Fixed18.wrap(price + 1e18);

        // The mutant returns the untransformed price = original price
        // Assert that the result matches expected transformed price
        assertTrue(Fixed18.unwrap(result.price) == Fixed18.unwrap(expectedPrice));
    }
}

