pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(
        string calldata _name,
        string calldata _symbol,
        uint256 _maintenance,
        uint256 _fundingFee,
        uint256 _makerFee,
        uint256 _takerFee,
        uint256 _positionFee,
        uint256 _makerLimit,
        int128 _minRate,
        int128 _maxRate,
        int128 _targetRate,
        uint128 _targetUtilization,
        address _oracle,
        bytes2 _payoffData,
        uint8 _payoffType,
        uint8 _payoffDirection
    ) public {
        vm.assume(_maintenance > 0);
        vm.assume(_fundingFee > 0 && _fundingFee <= 1e18);
        vm.assume(_makerFee > 0 && _makerFee <= 1e18);
        vm.assume(_takerFee > 0 && _takerFee <= 1e18);
        vm.assume(_positionFee > 0 && _positionFee <= 1e18);
        vm.assume(_makerLimit > 0);
        vm.assume(_payoffType <= 5);
        vm.assume(_payoffDirection <= 1);
        vm.assume(bytes(_name).length > 0);
        vm.assume(bytes(_symbol).length > 0);
        vm.assume(_oracle != address(0) && _oracle.code.length > 0);

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: _name,
            symbol: _symbol,
            payoffDefinition: PayoffDefinition({
