pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(PayoffDefinition memory definition) public {
        // Only payoff types that actually transform the price create a difference.
        // Restrict to valid definitions that are not the identity transformation.
        // The fuzzer supplies the definition; we assume it's valid and non-identity.
        // A valid definition requires payoffType < 8, payoffDirection < 2, and at least one of them is non-zero
        // to ensure the transformation is not identity (which would hide the bug).
        vm.assume(uint8(definition.payoffType) < 8);
        vm.assume(uint8(definition.payoffDirection) < 2);
        vm.assume(!(definition.payoffType == PayoffDefinitionLib.PayoffType(0) && definition.payoffDirection == PayoffDefinitionLib.PayoffDirection(0)));

        // Oracle that always returns a price of 1.5 * 1e18 (Fixed18).
        // The exact price doesn't matter as long as it is non-zero and transformation changes it.
        MockOracle oracle = new MockOracle();
        oracle.setPrice(Fixed18.wrap(1500000000000000000)); // 1.5e18

        // Use a minimal product info to satisfy initializer checks.
        // The product must be initialized with the fuzzed definition.
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "T";
        info.payoffDefinition = definition;
        info.oracle = IOracleProvider(address(oracle));
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(1000e18);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(1e18),
            PackedFixed18.wrap(0),
            PackedUFixed18.wrap(0)
        );

        // Initialize via the controller that created this product.
        // The test deploys a minimal controller that authorizes the product.
        MinimalController controller = new MinimalController();
        controller.setProduct(c);
        // The product's initializer checks that msg.sender is a controller.
        vm.prank(address(controller));
        c.initialize(info);

        // Call currentVersion on the reference and the mutant would have the bug.
        // The reference transforms the price, the mutant returns raw oracle price.
        IOracleProvider.OracleVersion memory version = c.currentVersion();
        Fixed18 transformedPrice = version.price;

        // Compute the expected transformed price using the payoff definition's transform logic.
        // This replicates the _transform function in UPayoffProvider.
        Fixed18 rawPrice = oracle.currentVersion().price;
        Fixed18 expectedTransformed = definition.transform(rawPrice);

        // The property: the returned price must equal the transformed price.
        assertTrue(Fixed18.unwrap(transformedPrice) == Fixed18.unwrap(expectedTransformed));
    }
}

// Minimal controller that authorizes product for initialization.
contract MinimalController {
    C public product;
